const double = (x) => x * 2;
test({ sr: 'pipe ide sleva nadesno', en: 'pipe goes left to right' }, () => {
  expect(pipe(add1, double)(3)).toBe(8);
});
test({ sr: 'compose ide zdesna nalevo', en: 'compose goes right to left' }, () => {
  expect(compose(add1, double)(3)).toBe(7);
});
test({ sr: 'jedna funkcija radi isto u oba slučaja', en: 'a single function behaves the same in both' }, () => {
  expect(pipe(double)(4)).toBe(8);
  expect(compose(double)(4)).toBe(8);
});

